use ini::parse;

fn get(src: &str, section: &str, key: &str) -> String {
    parse(src).unwrap().get(section).unwrap().get(key).unwrap().clone()
}

#[test]
fn top_level_keys_live_in_the_empty_section() {
    assert_eq!(get("name = armada\n", "", "name"), "armada");
}

#[test]
fn sections_group_their_keys() {
    let src = "[server]\nport = 8080\n[client]\nport = 9090\n";
    assert_eq!(get(src, "server", "port"), "8080");
    assert_eq!(get(src, "client", "port"), "9090");
}

#[test]
fn comments_and_blank_lines_are_ignored() {
    let src = "; a comment\n\n# another\nkey = value\n";
    assert_eq!(get(src, "", "key"), "value");
}

#[test]
fn quoted_values_keep_their_inner_whitespace_and_lose_the_quotes() {
    assert_eq!(get("k = \"  spaced  \"\n", "", "k"), "  spaced  ");
}

#[test]
fn a_later_key_overwrites_an_earlier_one_in_the_same_section() {
    assert_eq!(get("k = 1\nk = 2\n", "", "k"), "2");
}

#[test]
fn a_line_that_is_neither_section_comment_nor_pair_is_an_error() {
    let err = parse("this is not valid\n").unwrap_err();
    assert!(err.contains("1"), "the error must name the line number, got: {err}");
}

