pub fn parse(input: &str) -> Result<Ini, String> {
    let mut ini = Ini::new();
    let mut section = String::new();
    ini.insert(section.clone(), BTreeMap::new());

    for (idx, raw_line) in input.lines().enumerate() {
        let line = raw_line.trim();
        let line_no = idx + 1;

        if line.is_empty() || line.starts_with(';') || line.starts_with('#') {
            continue;
        }

        if line.starts_with('[') && line.ends_with(']') {
            section = line[1..line.len() - 1].trim().to_string();
            ini.entry(section.clone()).or_default();
            continue;
        }

        if let Some((key, value)) = line.split_once('=') {
            let key = key.trim().to_string();
            let value = value.trim();
            let value = if value.len() >= 2 && value.starts_with('"') && value.ends_with('"') {
                value[1..value.len() - 1].to_string()
            } else {
                value.to_string()
            };
            ini.entry(section.clone()).or_default().insert(key, value);
            continue;
        }

        return Err(format!("invalid line {line_no}: {raw_line}"));
    }

    Ok(ini)
}

